import { repository } from '../core/repository.js';
import { formatDate } from '../core/utils.js';
import { openComposer } from '../components/composer.js';
import { openEntryDetail, deleteEntry, profileMap, worldHeader, emptyState } from './shared.js';

export async function renderTimeline(container){
  container.innerHTML='';container.append(worldHeader({eyebrow:'TIMELINE',title:'Perjalanan yang tersusun oleh waktu.',subtitle:'Tonggak hubungan diurutkan berdasarkan tanggal kejadian, bukan berdasarkan waktu unggah.',actions:[{label:'＋ Tambah tonggak',primary:true,onClick:()=>openComposer({type:'timeline',onSaved:load})}]}));
  const timeline=document.createElement('div');timeline.className='timeline';container.append(timeline);
  async function load(){timeline.innerHTML='<div class="skeleton" style="min-height:300px;border-radius:28px"></div>';try{const entries=await repository.listEntries({type:'timeline',ascending:true});timeline.innerHTML='';if(!entries.length){timeline.append(emptyState('Timeline belum dimulai','Tambahkan tonggak pertama dan biarkan perjalanan kalian terbentuk dengan sendirinya.',()=>openComposer({type:'timeline',onSaved:load})));return;}const map=profileMap();for(const entry of entries){const item=document.createElement('article');item.className='timeline-item';const panel=document.createElement('div');panel.className='world-panel glass-panel';panel.innerHTML='<div class="entry-card__meta"><span></span><span></span></div><h3 style="font-size:1.45rem;margin:.65rem 0"></h3><p class="muted" style="line-height:1.65"></p><div class="toolbar" style="margin-top:14px;margin-bottom:0"><button class="button button--primary" data-open>Buka</button><button class="button button--ghost" data-edit>Edit</button><button class="button button--danger" data-delete>Hapus</button></div>';panel.querySelector('.entry-card__meta span:first-child').textContent=entry.event_date?formatDate(entry.event_date):formatDate(entry.created_at);panel.querySelector('.entry-card__meta span:last-child').textContent=map.get(entry.created_by)?.display_name||'';panel.querySelector('h3').textContent=entry.title;panel.querySelector('p').textContent=entry.body||`${entry.attachments?.length||0} lampiran`;panel.querySelector('[data-open]').onclick=()=>openEntryDetail(entry,{onChanged:load,origin:panel});panel.querySelector('[data-edit]').onclick=()=>openComposer({type:'timeline',entry,onSaved:load});panel.querySelector('[data-delete]').onclick=()=>deleteEntry(entry,load);item.append(panel);timeline.append(item);}}catch(error){timeline.innerHTML='';timeline.append(emptyState('Timeline gagal dimuat',error.message));}}
  await load();
}
